// This @MainActor ensures that app doesn't crash
@MainActor
class Account: ObservableObject {
    // @Published announces if the value in the variable changes
    @Published var userName = ""
    @Published var email = ""
    @Published var password = ""
    @Published var confirmedPassword = ""
    @Published var showOnboarding = false
    @Published var showDashboard = false
    @Published var isAccountCreated = false
    @Published var errorMessage = "" // The user will be able to use this instead of using print
    @Published var isLoading = false // This is for the spinning wheel for loading. This is to clarify user that the app didn't freeze
    
    // This function will handle the creating account process
    // Adding async lets createAccount run without freezing the app to maintain responsiveness
    func createAccount() async
    {
        
        // This clears any old errors
        errorMessage = ""
        
        // Checks for any errors when creating account
        let cleanUsername = userName.trimmingCharacters(in: .whitespacesAndNewlines)
        let cleanEmail = email.trimmingCharacters(in: .whitespacesAndNewlines)
        
        
        if (cleanUsername.isEmpty) {
            errorMessage = "Please enter a username"
            return
        }
        
        if cleanEmail.isEmpty || password.isEmpty {
            errorMessage = "Please enter the email or password to create an account"
            return
        }
        
        // Checks for valid email
        if !isValidEmail(cleanEmail)
        {
            errorMessage = "Please enter a valid email address"
            return
        }
        
        if (password != confirmedPassword) {
            errorMessage = "The Passwords do not match"
            return
        }
        
        // This is for the spinning wheel
        isLoading = true
        
        // Do catch that will handle the account creating process
        // This will send the account to PostgreSQL
        do {
            // Calls supabase
            // let ACCOUNT will pause the function(await) until supabase finishes processing the request
            let ACCOUNT = try await supabase.auth.signUp(email: cleanEmail, password: password, data: ["username": .string(cleanUsername)])
            
            // This will go through if the user successfully logged in
            showOnboarding = true
            isLoading = false
            print("Account Creation Successful! \(ACCOUNT.user.id)") // ACCOUNT.user.id will give a unique id (UUID string)
            
        } catch {
            // This is if the server rejects it
            isLoading = false
            errorMessage = error.localizedDescription // localizedDescription will show a readable error instead of a technical one
            print("There was an error creating your account: \(error.localizedDescription)")
        }
        
    }

    
    
    func loginUser() async {
        
        // Clear any old errors
        errorMessage = ""
        
        // Remove spaces from beginning and end of email
        let cleanedEmail = email.trimmingCharacters(
            in: .whitespacesAndNewlines
        )
        
        
        // Check for empty email
        if cleanedEmail.isEmpty {
            errorMessage = "Please enter your email."
            return
        }
        
        
        // Check email format
        if !isValidEmail(cleanedEmail) {
            errorMessage = "Please enter a valid email address."
            return
        }
        
        
        // Check for empty password
        if password.isEmpty {
            errorMessage = "Please enter your password."
            return
        }
        
        
        // Start loading
        isLoading = true
        
        
        do {
            
            // Attempt login with Supabase
            let ACCOUNT = try await supabase.auth.signIn(
                email: cleanedEmail,
                password: password
            )
            
            
            // Check whether onboarding has already been completed
            await checkProfileExists()
            
            
            // Stop loading
            isLoading = false
            
            print("Login Successful! \(ACCOUNT.user.id)")
            
            
        } catch {
            
            isLoading = false
            errorMessage = error.localizedDescription
            
            print(
                "There was an error logging in: \(error.localizedDescription)"
            )
        }
    }
    
    // This function will sign the current user out
    func signOutUser() async {
        
        // Clear any old errors
        errorMessage = ""
        
        // Start loading
        isLoading = true
        
        do {
            
            // End the user's Supabase session
            try await supabase.auth.signOut()
            
            
