            userName = ""
            email = ""
            password = ""
            confirmedPassword = ""
            
            
            // Return navigation back to AccountView
            showOnboarding = false
            showDashboard = false
            
            
            // Stop loading
            isLoading = false
            
            print("User signed out successfully.")
            
        } catch {
            
            // Stop loading
            isLoading = false
            
            errorMessage = "Could not sign out."
            
            print(
                "Sign out failed: \(error.localizedDescription)"
            )
        }
    }
    
    // This helper function checks for a valid email
    private func isValidEmail(_ email: String) -> Bool {
        
        let emailPattern =
            #"^[A-Z0-9a-z._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$"#
        
        return email.range(
            of: emailPattern,
            options: .regularExpression
        ) != nil
    }
    
    // This function will check if the user account exists already
    func checkProfileExists() async {
        guard let currentUserID = supabase.auth.currentUser?.id else { return }
        
        do {
            let profiles: [HealthProfile] = try await supabase
                .from("health_profiles")
                .select()
                .eq("user_id", value: currentUserID)
                .execute()
                .value
            
            // If profile has no onboarding data then show the onboarding
            if profiles.isEmpty {
                showOnboarding = true
                showDashboard = false
            }
            else {
                // if the user has onboarding data, take them to the main menu
                showOnboarding = false
                showDashboard = true
            }
            
        } catch {
            errorMessage = error.localizedDescription
            showOnboarding = true
        }
    }
    
    // This function will handle saving the onboarding data to Supabase
    func saveOnboardingDetails(
        age: Int,
        weight: Double,
        heightInches: Double,
        sex: String,
        goalType: String,
        startingValue: Double,
        targetValue: Double,
        goalUnit: String
    ) async {
        
        // Storing an empty string
        errorMessage = ""
        
        // Get the current user's ID
        guard let currentUserID = supabase.auth.currentUser?.id else {
            errorMessage = "User could not be found."
            return }
        
        // Package the data into one health profile
        let healthProfile = HealthProfile(
            user_id: currentUserID,
            age: age,
            height_inches: heightInches,
            biological_sex: sex
        )
        
        // Package the data into NewWeightLog
        let initialWeight = NewWeightLog(user_id: currentUserID, weight_lbs: weight)
        
        // Package the data into NewGoal
        let initialGoal = NewGoal (
            user_id: currentUserID,
            goal_type: goalType,
            starting_value: startingValue,
            target_value: targetValue,
            unit: goalUnit
        )
        
        // Spinning wheel
        isLoading = true
        
        do {
            try await supabase
                .from("health_profiles")
                .upsert(healthProfile)
                .execute()
            
            try await supabase
                .from("weight_logs")
                .insert(initialWeight)
                .execute()
            
            try await supabase
                .from("goals")
                .insert(initialGoal)
                .execute()
            
            isLoading = false // spinning wheel
            showOnboarding = false
            showDashboard = true
            
            print("Successfully saved the onboarding data!")
            
        } catch {
            isLoading = false // spinning wheel
            errorMessage = error.localizedDescription
            print("Error saving onboarding data: \(error.localizedDescription)")
        }
    }
    
}
